-- Product redesign data model (PRD 15.3). Everything here is ADDED beside the legacy models:
-- no legacy table or column is changed or dropped; that happens in a later migration, after
-- `npm --prefix backend run migrate:verify-redesign` has confirmed the conversion.
--
-- Part 1  pre-flight check
-- Part 2  schema, as generated by Prisma, except that "User"."usernameLower" and
--         "User"."friendCode" are added nullable here and constrained in part 5
-- Part 3  SQL helpers that keep those two columns valid for every writer
-- Part 4  conversion of the existing user data (reads the legacy tables only)
-- Part 5  constraints on the backfilled columns
--
-- Prisma sends this file as one statement batch, so PostgreSQL runs it in a single transaction:
-- a failure anywhere leaves the database untouched.

-- ===== Part 1: pre-flight check =====

-- "usernameLower" is unique, so usernames that differ only by case must be renamed by hand first.
DO $$
DECLARE
  colliding_usernames text;
BEGIN
  SELECT string_agg(collision.usernames, '; ') INTO colliding_usernames
  FROM (
    SELECT string_agg("username", ', ' ORDER BY "username") AS usernames
    FROM "User"
    GROUP BY lower("username")
    HAVING count(*) > 1
  ) AS collision;

  IF colliding_usernames IS NOT NULL THEN
    RAISE EXCEPTION 'Usernames that differ only by case must be renamed before this migration: %', colliding_usernames;
  END IF;
END $$;

