-- ===== Part 3: SQL helpers =====

-- Default of "User"."friendCode": 8 characters from an alphabet without look-alikes
-- (no 0, O, 1, I, L), retried until unused. Randomness comes from gen_random_uuid(), which is
-- cryptographically strong; hashing it gives 32 uniform bytes, two per character.
CREATE FUNCTION generate_friend_code() RETURNS text
LANGUAGE plpgsql VOLATILE
SET search_path FROM CURRENT
AS $$
DECLARE
  alphabet CONSTANT text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  random_bytes bytea;
  candidate text;
BEGIN
  LOOP
    random_bytes := sha256(uuid_send(gen_random_uuid()));

    SELECT string_agg(
             substr(
               alphabet,
               1 + (get_byte(random_bytes, 2 * character_position) * 256 + get_byte(random_bytes, 2 * character_position + 1)) % length(alphabet),
               1
             ),
             '' ORDER BY character_position
           )
    INTO candidate
    FROM generate_series(0, 7) AS character_position;

    EXIT WHEN NOT EXISTS (SELECT 1 FROM "User" WHERE "friendCode" = candidate);
  END LOOP;

  RETURN candidate;
END $$;

-- "User"."usernameLower" is always lower("username"), whichever code path writes the row.
CREATE FUNCTION set_user_username_lower() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW."usernameLower" := lower(NEW."username");
  RETURN NEW;
END $$;

CREATE TRIGGER "User_usernameLower_sync"
BEFORE INSERT OR UPDATE OF "username", "usernameLower" ON "User"
FOR EACH ROW EXECUTE FUNCTION set_user_username_lower();

-- ===== Part 4: data conversion =====

-- 4.1 XP, level and streak move from the per-level "UserProgress" rows to the user (PRD 6.8).
--   xpTotal = floor(sum of the user's legacy xpTotal / 25): the legacy 250 XP per answer becomes 10.
--   level   = the highest n with 50 * n * (n + 1) / 2 <= xpTotal, and 1 below 150 XP. This is
--             levelForXp() of @project/xp-constants; migrate:verify-redesign compares the two.
--             The series only needs to reach sqrt(xpTotal / 25), because n * n < n * (n + 1).
--   streak  = the highest streakCurrent across the rows, with the dates of the row that holds it
--             (ties: the latest streakLastActivityDate). streakBest starts at the same value.
-- A user without progress rows keeps the column defaults.
WITH converted AS (
  SELECT "userId",
         floor(sum("xpTotal") / 25.0)::int AS xp_total,
         max("streakCurrent") AS streak
  FROM "UserProgress"
  GROUP BY "userId"
),
streak_source AS (
  SELECT DISTINCT ON ("userId") "userId", "streakLastActivityDate", "streakLastCheckedDate"
  FROM "UserProgress"
  ORDER BY "userId", "streakCurrent" DESC, "streakLastActivityDate" DESC NULLS LAST, "id"
)
UPDATE "User"
SET "xpTotal" = converted.xp_total,
    "level" = COALESCE((
      SELECT max(n)::int
      FROM generate_series(2, ceil(sqrt(converted.xp_total / 25.0))::bigint) AS n
      WHERE 50 * n * (n + 1) / 2 <= converted.xp_total
    ), 1),
    "streakCurrent" = converted.streak,
    "streakBest" = converted.streak,
    "streakLastActivityDate" = streak_source."streakLastActivityDate",
    "streakLastCheckedDate" = streak_source."streakLastCheckedDate"
FROM converted
JOIN streak_source USING ("userId")
WHERE "User"."id" = converted."userId";

-- 4.2 The chosen experience level becomes the starting track. The legacy minutes goal has no
--     equivalent, so weeklyGoalDays and dailyGoalLessons keep their defaults.
UPDATE "User"
SET "startingTrack" = (CASE "activeExperienceLevel"
      WHEN 'JUNIOR' THEN 'BEGINNER'
      WHEN 'MID' THEN 'INTERMEDIATE'
      WHEN 'SENIOR' THEN 'ADVANCED'
    END)::"Track"
WHERE "activeExperienceLevel" IS NOT NULL;

-- 4.3 Sign-in identities. Legacy accounts were never linked after sign-up, so the identity is as
--     old as the account.
INSERT INTO "AuthIdentity" ("provider", "subject", "userId", "createdAt")
SELECT 'GOOGLE'::"AuthProvider", "googleId", "id", "createdAt" FROM "User" WHERE "googleId" IS NOT NULL
UNION ALL
SELECT 'APPLE'::"AuthProvider", "appleSub", "id", "createdAt" FROM "User" WHERE "appleSub" IS NOT NULL;

-- 4.4 Every finished duel becomes a match that keeps the legacy id.
--   A session a user played against a copy of themselves (player1Id = player2Id) becomes a GHOST
--   practice game, which no win count includes (PRD 11.6 "Data fix").
--   The legacy "startedAt" column holds the END time (PRD 2.7), so both timestamps get the end time.
--   The questions of old games cannot be recovered (PRD 15.3), so itemIds stays empty.
INSERT INTO "Match" ("id", "mode", "track", "rounds", "itemIds", "startedAt", "endedAt")
SELECT "id",
       (CASE WHEN "player1Id" = "player2Id" THEN 'GHOST' ELSE 'RANKED' END)::"MatchMode",
       'BEGINNER'::"Track",
       "roundsPlayed",
       ARRAY[]::TEXT[],
       COALESCE("endedAt", "startedAt"),
       COALESCE("endedAt", "startedAt")
FROM "DuelSession";

-- 4.5 One participant per player: seat 0 is player 1, seat 1 is player 2; a self-play session has
--     seat 0 only. The winner is placed 1 and the loser 2; a draw (no winner) places both 1.
--     Legacy scoring gave one point to whoever answered a round correctly first, so the score is
--     also the number of correct answers. "roundReplay" records, per round, who that was and their
--     answer time; the other player's answer and time were never stored.
WITH seat AS (
  SELECT duel."id" AS match_id,
         duel."winnerId" AS winner_id,
         CASE WHEN jsonb_typeof(duel."roundReplay") = 'array' THEN duel."roundReplay" ELSE '[]'::jsonb END AS legacy_rounds,
         player.seat_number,
         player.user_id,
         player.score,
         player.answer_time_key
  FROM "DuelSession" AS duel
  CROSS JOIN LATERAL (VALUES
    (0, duel."player1Id", duel."player1Score", 'player1TimeMs'),
    (1, duel."player2Id", duel."player2Score", 'player2TimeMs')
  ) AS player(seat_number, user_id, score, answer_time_key)
  WHERE player.seat_number = 0 OR duel."player1Id" <> duel."player2Id"
)
INSERT INTO "MatchParticipant" ("id", "matchId", "userId", "seat", "placement", "score", "correctCount", "correctTimeMs", "answers")
SELECT seat.match_id || '_seat' || seat.seat_number,
       seat.match_id,
       seat.user_id,
       seat.seat_number,
       CASE WHEN seat.winner_id IS NULL OR seat.winner_id = seat.user_id THEN 1 ELSE 2 END,
       seat.score,
       seat.score,
       replay.correct_time_ms,
       replay.answers
FROM seat
CROSS JOIN LATERAL (
  SELECT COALESCE(sum(played_round.answer_time_ms) FILTER (WHERE played_round.answered_first), 0)::int AS correct_time_ms,
         COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'round', played_round.round_number,
               'correct', played_round.answered_first,
               'timeMs', CASE WHEN played_round.answered_first THEN played_round.answer_time_ms END,
               'points', played_round.answered_first::int
             )
             ORDER BY played_round.round_position
           ),
           '[]'::jsonb
         ) AS answers
  FROM (
    SELECT legacy_round.round_position,
           (legacy_round.entry ->> 'roundNumber')::int AS round_number,
           COALESCE(legacy_round.entry ->> 'winnerUserId' = seat.user_id, false) AS answered_first,
           round((legacy_round.entry ->> seat.answer_time_key)::numeric)::int AS answer_time_ms
    FROM jsonb_array_elements(seat.legacy_rounds) WITH ORDINALITY AS legacy_round(entry, round_position)
  ) AS played_round
) AS replay;

-- 4.6 Backfill of the two derived identity columns.
UPDATE "User" SET "usernameLower" = lower("username");

-- One row at a time, so that generate_friend_code() sees the codes already handed out.
DO $$
DECLARE
  user_id text;
BEGIN
  FOR user_id IN SELECT "id" FROM "User" WHERE "friendCode" IS NULL LOOP
    UPDATE "User" SET "friendCode" = generate_friend_code() WHERE "id" = user_id;
  END LOOP;
END $$;

-- ===== Part 5: constraints on the backfilled columns =====

-- The empty default only lets a writer omit "usernameLower"; the trigger always replaces it.
ALTER TABLE "User"
  ALTER COLUMN "usernameLower" SET NOT NULL,
  ALTER COLUMN "usernameLower" SET DEFAULT '',
  ALTER COLUMN "friendCode" SET NOT NULL,
  ALTER COLUMN "friendCode" SET DEFAULT generate_friend_code();

-- CreateIndex
CREATE UNIQUE INDEX "User_usernameLower_key" ON "User"("usernameLower");

-- CreateIndex
CREATE UNIQUE INDEX "User_friendCode_key" ON "User"("friendCode");

-- CreateIndex
CREATE INDEX "User_usernameLower_prefix_idx" ON "User"("usernameLower" text_pattern_ops);
